code.default:
try:
    vars['route'] = 'stale'
    if str(vars.get('t_create_promise_response.data.ok') or '').lower() in ('true', 'yes'):
        vars['promise_recorded'] = 'yes'
    for k in list(vars):
        sk = str(k)
        if '.header.' in sk or sk.endswith('_response.message') or sk.endswith('_response.error') or sk.startswith('system.'):
            vars.pop(k, None)
    if vars.get('promise_recorded') == 'yes':
        vars['close_outcome'] = "promise"
        vars['close_reason'] = ''
    if str(vars.get('w_go_verify_identity') or '') != 'go':
        vars['w_go_verify_identity'] = 'done'
    if str(vars.get('w_go_get_account') or '') != 'go':
        vars['w_go_get_account'] = 'done'
    if str(vars.get('w_go_create_promise') or '') != 'go':
        vars['w_go_create_promise'] = 'done'
    if str(vars.get('w_go_add_note') or '') != 'go':
        vars['w_go_add_note'] = 'done'
    if str(vars.get('w_go_schedule_callback') or '') != 'go':
        vars['w_go_schedule_callback'] = 'done'
    if str(vars.get('w_go_transfer_to_agent') or '') != 'go':
        vars['w_go_transfer_to_agent'] = 'done'
except Exception:
    vars['route'] = 'stale'

